<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');require_once dirname(__DIR__,2).'/app/Services/AdminOperationsService.php';$svc=new AdminOperationsService(Database::connection());$q=trim($_GET['q']??'');$rows=$svc->customerSearch($q);$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$svc->setCustomerStatus((int)$_POST['id'],$_POST['status']);$success='Customer status updated.';$rows=$svc->customerSearch($q);}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customers - Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2>Customer Operations</h2><a href="<?=url('admin/')?>">Admin dashboard</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><form class="mb-4"><div class="input-group"><input name="q" value="<?=e($q)?>" class="form-control" placeholder="Name or email"><button class="btn btn-primary">Search</button></div></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Customer</th><th>Email</th><th>Status</th><th>Accounts</th><th>Balance</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['status'])?></td><td><?=e((string)$r['accounts'])?></td><td>$<?=number_format((float)$r['balance'],2)?></td><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="form-select form-select-sm"><option>active</option><option>suspended</option><option>locked</option></select><button class="btn btn-sm btn-outline-primary">Update</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></body></html>
